export type ScriptLifecycleState='READY_TO_DELIVER'|'TRANSCRIPT_AVAILABLE_FOR_SEMANTIC_REVIEW'|'DELIVERED_WAITING_FOR_BUYER'|'BUYER_RESPONSE_RECEIVED';
